from concurrent.futures import ThreadPoolExecutor


def square(x: int) -> int:
    return x * x


def squares(xs: list[int]) -> list[int]:
    """Return [square(x) for x in xs], computing each element in a thread pool.

    The output preserves the order of the input. An empty input returns an
    empty list.
    """
    with ThreadPoolExecutor() as pool:
        return list(pool.map(square, xs))


def test_squares_preserves_order() -> None:
    assert squares([3, 1, 4, 1, 5]) == [9, 1, 16, 1, 25]


def test_squares_empty() -> None:
    assert squares([]) == []


def test_squares_negative_values() -> None:
    assert squares([-2, 0, -7]) == [4, 0, 49]
